from dataclasses import dataclass

@dataclass
class Grounded:
    answer: str | None       # None means: the documents do not address this
    clause_id: str | None
    quote: str | None

SYSTEM = """Answer only from the numbered clauses provided.

Return JSON: {"clause_id": "<id or null>", "quote": "<verbatim text or null>",
              "answer": "<one sentence, or null>"}

If the clauses do not address the question, return all three as null. Returning
null is a correct and expected outcome — do not infer, generalise from similar
clauses, or answer from general knowledge about contracts."""

def ask(question: str, clauses: list[dict], client) -> Grounded:
    context = "\n\n".join(f"[{c['id']}] {c['text']}" for c in clauses)
    raw = client.complete(system=SYSTEM,
                          user=f"Clauses:\n{context}\n\nQuestion: {question}",
                          response_format="json")

    if not raw.get("clause_id"):
        return Grounded(None, None, None)          # refusal: a normal result

    # A model will occasionally cite an id that was never in the context. An
    # unvalidated citation is worse than none, because it looks like evidence.
    by_id = {c["id"]: c["text"] for c in clauses}
    if raw["clause_id"] not in by_id:
        log.warning("hallucinated clause id %r for question %r", raw["clause_id"], question)
        return Grounded(None, None, None)

    # The quote must actually appear in the cited clause, not merely resemble it.
    source = by_id[raw["clause_id"]]
    quote = (raw.get("quote") or "").strip()
    if not quote or quote not in source:
        log.warning("quote not found verbatim in clause %s", raw["clause_id"])
        return Grounded(None, None, None)

    return Grounded(raw["answer"], raw["clause_id"], quote)


# The renderer has no way to show an uncited claim — the type makes it impossible.
def render(g: Grounded) -> str:
    if g.answer is None:
        return "Not stated in the contract."
    return f"{g.answer}\n\n> [{g.clause_id}] {g.quote}"
